"use client";

// Dependencies: npm i gsap @gsap/react
// Y2K Dreamy Bloom Text Component — Goodmotion (https://goodmotion.vercel.app/)

import React, { useRef, useMemo, type CSSProperties } from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";

// Register GSAP plugins safely
if (typeof window !== "undefined") {
    gsap.registerPlugin(useGSAP);
}

export interface DreamyBloomProps {
    children?: React.ReactNode;
    text?: string;
    className?: string;
    color?: string;
    fontSize?: number | string;
    fontWeight?: number | string;
    fontFamily?: string;
    letterSpacing?: number | string;
    lineHeight?: number | string;
    rimLightRadius?: number;
    maxStrokeWidth?: number;
    scaleBoost?: number;
    hoverProximity?: number;
    autoSweepDuration?: number;
    edgeBlur?: number;
    style?: CSSProperties;
}

export function DreamyBloom({
    children,
    text = "code component glow text - built by goodmotion.vercel.app",
    className = "",
    color = "#FFFFFF",
    fontSize = 58,
    fontWeight = 700,
    fontFamily = "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
    letterSpacing = -6,
    lineHeight = 0.85,
    rimLightRadius = 5.5,
    maxStrokeWidth = 6,
    scaleBoost = 1.21,
    hoverProximity = 150,
    autoSweepDuration = 10,
    edgeBlur = 1,
    style,
}: DreamyBloomProps) {
    const containerRef = useRef<HTMLDivElement>(null);
    const contentText = typeof children === "string" ? children : text;

    // Self-contained word & character tokenizer (Free of paid SplitText plugin)
    const { wordsData, totalChars } = useMemo(() => {
        const rawLines = contentText.split("\n");
        let globalIndexCounter = 0;

        const parsedLines = rawLines.map((line) => {
            const rawWords = line.split(" ");
            return rawWords.map((word, wIdx) => {
                const chars = Array.from(word).map((char) => ({
                    char,
                    globalIndex: globalIndexCounter++,
                }));
                const hasTrailingSpace = wIdx < rawWords.length - 1;
                if (hasTrailingSpace) {
                    globalIndexCounter++;
                }
                return { chars, hasTrailingSpace };
            })
        });

        return { wordsData: parsedLines, totalChars: globalIndexCounter };
    }, [contentText]);

    // Scoped lifecycle management via useGSAP
    useGSAP(
        () => {
            const container = containerRef.current;
            if (!container || totalChars === 0) return;

            const charElements = container.querySelectorAll<HTMLSpanElement>(".bloom-char");
            if (!charElements.length) return;

            // Interactive state trackers
            const sweepTracker = { progress: 0 };
            let mousePos: { x: number; y: number } | null = null;

            // 1. Concurrent Auto Sweep continuous timeline
            const sweepTimeline = gsap.to(sweepTracker, {
                progress: 1,
                duration: Math.max(1, autoSweepDuration),
                repeat: -1,
                ease: "none",
            });

            // 2. High-performance animation frame loop
            const updateFrame = () => {
                const containerRect = container.getBoundingClientRect();
                const currentProgress = sweepTracker.progress;
                const sweepCenter = currentProgress * (totalChars + 4) - 2;
                const sweepSpread = 2.4;

                charElements.forEach((charEl) => {
                    const idx = Number(charEl.dataset.index || 0);

                    // Auto Sweep Wave intensity
                    let autoFactor = 0;
                    const distToSweep = Math.abs(idx - sweepCenter);
                    if (distToSweep < sweepSpread) {
                        autoFactor = Math.cos((distToSweep / sweepSpread) * (Math.PI / 2));
                    }

                    // Hover Proximity intensity
                    let mouseFactor = 0;
                    if (mousePos) {
                        const charRect = charEl.getBoundingClientRect();
                        const charCenterX = charRect.left - containerRect.left + charRect.width / 2;
                        const charCenterY = charRect.top - containerRect.top + charRect.height / 2;
                        const dist = Math.hypot(mousePos.x - charCenterX, mousePos.y - charCenterY);

                        if (dist < hoverProximity) {
                            const norm = dist / hoverProximity;
                            mouseFactor = Math.cos((norm * Math.PI) / 2);
                        }
                    }

                    // Combined non-destructive force (clamped to 1.0)
                    const factor = Math.min(1, mouseFactor + autoFactor * 0.75);

                    // Compute dynamic optical properties
                    const strokeWidth = factor * maxStrokeWidth;
                    const scale = 1 + factor * (scaleBoost - 1);
                    const r = rimLightRadius * (1 + factor * 1.6);
                    const blurVal = edgeBlur * (0.6 + factor * 0.8);

                    // Apply visual styling directly
                    charEl.style.transform = `scale(${scale})`;
                    charEl.style.webkitTextStroke = `${strokeWidth}px ${color}`;
                    charEl.style.filter = `blur(${blurVal}px)`;
                    charEl.style.textShadow = `
                        0 0 ${r * 0.25}px ${color},
                        0 0 ${r * 0.55}px ${color},
                        0 0 ${r * 1.05}px ${color},
                        0 0 ${r * 1.65}px ${color},
                        0 0 ${r * 2.4}px rgba(255, 255, 255, ${0.8 + factor * 0.2})
                    `;
                });
            };

            gsap.ticker.add(updateFrame);

            // Pointer event handlers scoped to container
            const handlePointerMove = (e: PointerEvent) => {
                const rect = container.getBoundingClientRect();
                mousePos = {
                    x: e.clientX - rect.left,
                    y: e.clientY - rect.top,
                };
            };

            const handlePointerLeave = () => {
                mousePos = null;
            };

            container.addEventListener("pointermove", handlePointerMove);
            container.addEventListener("pointerleave", handlePointerLeave);

            // Strict cleanup on unmount
            return () => {
                sweepTimeline.kill();
                gsap.ticker.remove(updateFrame);
                container.removeEventListener("pointermove", handlePointerMove);
                container.removeEventListener("pointerleave", handlePointerLeave);
            };
        },
        { scope: containerRef, dependencies: [totalChars, autoSweepDuration, maxStrokeWidth, scaleBoost, rimLightRadius, edgeBlur, hoverProximity, color] }
    );

    const formattedFontSize = typeof fontSize === "number" ? `${fontSize}px` : fontSize;
    const formattedLetterSpacing = typeof letterSpacing === "number" ? `${letterSpacing}px` : letterSpacing;

    return (
        <div
            ref={containerRef}
            className={`bloom-text-container ${className}`}
            style={{
                position: "relative",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                justifyContent: "center",
                cursor: "default",
                userSelect: "none",
                textAlign: "center",
                padding: "24px",
                background: "transparent",
                boxSizing: "border-box",
                width: "100%",
                height: "auto",
                ...style,
            }}
        >
            <div
                className="bloom-text-wrapper"
                style={{
                    position: "relative",
                    display: "flex",
                    flexDirection: "column",
                    alignItems: "center",
                    justifyContent: "center",
                    fontFamily,
                    fontSize: formattedFontSize,
                    fontWeight,
                    letterSpacing: formattedLetterSpacing,
                    lineHeight,
                    color,
                    background: "transparent",
                    width: "100%",
                }}
            >
                {wordsData.map((lineWords, lineIndex) => (
                    <div
                        key={lineIndex}
                        style={{
                            display: "flex",
                            flexWrap: "wrap",
                            justifyContent: "center",
                            alignItems: "center",
                            width: "100%",
                        }}
                    >
                        {lineWords.map((wordObj, wordIndex) => (
                            <span
                                key={wordIndex}
                                style={{
                                    display: "inline-flex",
                                    alignItems: "center",
                                    whiteSpace: "nowrap",
                                }}
                            >
                                {wordObj.chars.map((item, charIndex) => (
                                    <span
                                        key={charIndex}
                                        data-index={item.globalIndex}
                                        className="bloom-char"
                                        style={{
                                            position: "relative",
                                            display: "inline-block",
                                            color,
                                            paintOrder: "stroke fill",
                                            transformOrigin: "center center",
                                            willChange: "transform, text-shadow, filter, -webkit-text-stroke",
                                            transition: "transform 0.08s ease-out, -webkit-text-stroke 0.08s ease-out, text-shadow 0.08s ease-out, filter 0.08s ease-out",
                                        }}
                                    >
                                        {item.char}
                                    </span>
                                ))}
                                {wordObj.hasTrailingSpace && (
                                    <span style={{ display: "inline-block", width: "0.28em" }}>
                                        &nbsp;
                                    </span>
                                )}
                            </span>
                        ))}
                    </div>
                ))}
            </div>
        </div>
    );
}

// Dual export for flexible consumer imports
export default DreamyBloom;

